/bin/bash -lc "command -v pvpython || true; command -v paraview || true; command -v pvbatch || true; python3 - <<'PY'
try:
 import paraview
 print('paraview py',paraview.__file__)
except Exception as e: print('no pv',e)
try:
 import vtk
 print('vtk',vtk.VTK_VERSION)
except Exception as e: print('no vtk',e)
PY"

