/bin/bash -lc "/opt/conda/bin/pvpython - <<'PY'
from paraview.simple import *
r=XMLImageDataReader(FileName=['/workspace/Ocean.vti']); r.UpdatePipeline()
di=r.GetDataInformation(); print(di.GetBounds(),di.GetNumberOfPoints(),di.GetNumberOfCells())
for a in ['A','B','C','D']:
 x=di.GetPointDataInformation().GetArray(a); print(a, x.GetNumberOfComponents(),x.GetComponentRange(0))
# try names
for name in ['TensorEigenvector','Eigenvector','Tensor','Tetrahedralize','TTKTensor']:
 try:
  o=getattr(__import__('paraview.simple',fromlist=[name]),name)()
  print('found',name,o)
 except Exception as e: print('no',name,str(e)[:80])
PY"

